from html.parser import HTMLParser

VOID = {'meta','link','img','br','hr','input','source','area','base','col','embed','track','wbr'}

class Checker(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.ids = {}
        self.errors = []
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if 'id' in d:
            self.ids.setdefault(d['id'], 0)
            self.ids[d['id']] += 1
        if tag not in VOID:
            self.stack.append((tag, self.getpos()))
    def handle_startendtag(self, tag, attrs):
        d = dict(attrs)
        if 'id' in d:
            self.ids.setdefault(d['id'], 0)
            self.ids[d['id']] += 1
    def handle_endtag(self, tag):
        if tag in VOID:
            return
        if not self.stack:
            self.errors.append(f"stray </{tag}> at {self.getpos()}")
            return
        open_tag, pos = self.stack.pop()
        if open_tag != tag:
            self.errors.append(f"mismatch: <{open_tag}> opened at {pos}, closed by </{tag}> at {self.getpos()}")

src = open('index.html').read()
c = Checker()
c.feed(src)
c.close()
for e in c.errors:
    print("ERR", e)
for t, pos in c.stack:
    print("UNCLOSED", t, pos)
dupes = [k for k, v in c.ids.items() if v > 1]
if dupes:
    print("DUPLICATE IDS:", dupes)

# anchor targets must resolve to existing ids or external/http refs
import re
for href in re.findall(r'href="#([^"]+)"', src):
    if href and href not in c.ids:
        print("BROKEN ANCHOR:", href)
print("ids:", sorted(c.ids))
print("OK" if not c.errors and not c.stack and not dupes else "PROBLEMS FOUND")
EOF
